import JSON

"""
	gen( x, lambda, name )

Generate fixture data and write to file.

The CDF is evaluated in extended precision from the textbook formula `1 - exp(-lambda*x)`, as subtracting `exp(-lambda*x)` from `1` in double precision cancels for small `lambda*x` (to `0` for `lambda*x < 2^-53`).

# Arguments

* `x`: input value
* `lambda`: rate parameter
* `name::AbstractString`: output filename
"""
function gen( x, lambda, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( 1 .- exp.( .-BigFloat.( lambda ) .* BigFloat.( x ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("lambda", lambda),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Small `x`:
x = exp10.( range( -300.0, stop = -1.0, length = 1000 ) );
lambda = ( rand( 1000 ) .* 10.0 ) .+ 0.1;
gen( x, lambda, "small_x.json" );
